// Self-checking testbench for skid_buffer.
// Two lanes (WIDTH 8 and WIDTH 1) share control; both are checked every
// cycle against a reference queue of up to two beats.
`default_nettype none

module skid_buffer_tb;

    reg        clk     = 1'b0;
    reg        rst_n   = 1'b0;
    reg        s_valid = 1'b0;
    reg  [7:0] s_data  = 8'h00;
    reg        m_ready = 1'b0;

    wire       s_ready8;
    wire       m_valid8;
    wire [7:0] m_data8;
    wire       s_ready1;
    wire       m_valid1;
    wire [0:0] m_data1;

    skid_buffer #(.WIDTH(8)) dut8 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready8),
        .s_data  (s_data),
        .m_valid (m_valid8),
        .m_ready (m_ready),
        .m_data  (m_data8)
    );

    skid_buffer #(.WIDTH(1)) dut1 (
        .clk     (clk),
        .rst_n   (rst_n),
        .s_valid (s_valid),
        .s_ready (s_ready1),
        .s_data  (s_data[0:0]),
        .m_valid (m_valid1),
        .m_ready (m_ready),
        .m_data  (m_data1)
    );

    always #5 clk = ~clk;

    // Bookkeeping
    integer passed;
    integer failed;
    integer okarg;
    integer i;
    integer count;          // beats the model holds (0..2)
    reg [7:0]  q0;          // oldest beat
    reg [7:0]  q1;          // newer beat
    reg        s_fire_m;
    reg        m_fire_m;
    reg        stalled;     // a beat was offered and not taken on the last edge
    reg [7:0]  stall_data;
    reg        reset_pending;
    reg [31:0] rnd;
    reg [7:0]  dcount;
    reg [7:0]  tmp8;
    reg [3:0]  thr_s;
    reg [3:0]  thr_m;
    reg        g_sr8;
    reg        g_mv8;
    reg [7:0]  g_md8;
    reg        g_sr1;
    reg        g_mv1;
    reg [0:0]  g_md1;
    reg [8*64-1:0] nonce;

    task chk;
        input        ok;
        input [31:0] id;
        begin
            if (ok === 1'b1) begin
                passed = passed + 1;
            end else begin
                failed = failed + 1;
                $error("check %0d failed at time %0t (model count %0d, q0 %h)",
                       id, $time, count, q0);
            end
        end
    endtask

    task check_outputs;
        begin
            chk(m_valid8 === (count != 0), 1);
            chk(s_ready8 === (count < 2), 2);
            chk(m_valid1 === (count != 0), 3);
            chk(s_ready1 === (count < 2), 4);
            if (count != 0) begin
                chk(m_data8 === q0, 5);
                chk(m_data1 === q0[0:0], 6);
            end
            if (stalled) begin
                chk(m_valid8 === 1'b1 && m_data8 === stall_data, 7);
                chk(m_valid1 === 1'b1 && m_data1 === stall_data[0:0], 8);
            end
            if (reset_pending) begin
                chk(m_valid8 === 1'b0 && s_ready8 === 1'b1 &&
                    m_valid1 === 1'b0 && s_ready1 === 1'b1, 9);
                reset_pending = 1'b0;
            end
        end
    endtask

    // One clock cycle. Called just after a rising edge; returns just after
    // the next one with the model updated.
    task cycle;
        input       sv;
        input [7:0] sd;
        input       mr;
        begin
            #1;
            rst_n   = 1'b1;
            s_valid = sv;
            s_data  = sd;
            m_ready = mr;
            #1;
            check_outputs;
            // No combinational path from inputs to outputs.
            g_sr8 = s_ready8; g_mv8 = m_valid8; g_md8 = m_data8;
            g_sr1 = s_ready1; g_mv1 = m_valid1; g_md1 = m_data1;
            s_valid = ~sv;
            m_ready = ~mr;
            s_data  = ~sd;
            #1;
            chk(s_ready8 === g_sr8 && s_ready1 === g_sr1, 10);
            chk(m_valid8 === g_mv8 && m_data8 === g_md8 &&
                m_valid1 === g_mv1 && m_data1 === g_md1, 11);
            s_valid = sv;
            m_ready = mr;
            s_data  = sd;
            #1;
            s_fire_m   = sv && (count < 2);
            m_fire_m   = mr && (count != 0);
            stalled    = (count != 0) && !mr;
            stall_data = q0;
            @(posedge clk);
            if (m_fire_m) begin
                q0    = q1;
                count = count - 1;
            end
            if (s_fire_m) begin
                if (count == 0) q0 = sd;
                else            q1 = sd;
                count = count + 1;
            end
        end
    endtask

    // Two cycles of reset with random traffic on the ports.
    task do_reset;
        integer k;
        begin
            for (k = 0; k < 2; k = k + 1) begin
                #1;
                rnd     = $random;
                rst_n   = 1'b0;
                s_valid = rnd[0];
                m_ready = rnd[1];
                s_data  = rnd[15:8];
                @(posedge clk);
            end
            count         = 0;
            stalled       = 1'b0;
            reset_pending = 1'b1;
        end
    endtask

    // Direct look at the outputs just after an edge.
    task peek_state;
        input        exp_mv;
        input        exp_sr;
        input [31:0] id;
        begin
            #1;
            chk(m_valid8 === exp_mv && s_ready8 === exp_sr &&
                m_valid1 === exp_mv && s_ready1 === exp_sr, id);
        end
    endtask

    initial begin
        passed        = 0;
        failed        = 0;
        count         = 0;
        q0            = 8'h00;
        q1            = 8'h00;
        s_fire_m      = 1'b0;
        m_fire_m      = 1'b0;
        stalled       = 1'b0;
        stall_data    = 8'h00;
        reset_pending = 1'b0;
        dcount        = 8'h00;
        tmp8          = 8'h40;
        thr_s         = 4'd8;
        thr_m         = 4'd8;
        nonce         = {(8*64){1'b0}};
        okarg = $value$plusargs("nirmaan_nonce=%s", nonce);

        // 1. Reset values (reset applied with traffic on the ports)
        do_reset;
        peek_state(1'b0, 1'b1, 20);

        // 2. One-cycle latency: not offered on the accept edge, offered after
        cycle(1'b1, 8'hA5, 1'b1);
        #1;
        chk(m_valid8 === 1'b1 && m_data8 === 8'hA5 &&
            m_valid1 === 1'b1 && m_data1 === 1'b1, 21);
        cycle(1'b0, 8'h00, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        peek_state(1'b0, 1'b1, 22);

        // 3. Full throughput: one in and one out on every edge
        for (i = 0; i < 64; i = i + 1) begin
            cycle(1'b1, dcount, 1'b1);
            dcount = dcount + 8'd1;
            chk(s_fire_m === 1'b1, 23);
            if (i > 0) chk(m_fire_m === 1'b1, 24);
        end
        cycle(1'b0, 8'h00, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        peek_state(1'b0, 1'b1, 25);

        // 4. Stall: one beat held, a second must be accepted
        cycle(1'b1, 8'h11, 1'b0);
        peek_state(1'b1, 1'b1, 26);
        cycle(1'b1, 8'h22, 1'b0);
        chk(s_fire_m === 1'b1, 27);
        peek_state(1'b1, 1'b0, 28);
        // Two beats held: a third must not be accepted
        cycle(1'b1, 8'h33, 1'b0);
        chk(s_fire_m === 1'b0, 29);
        peek_state(1'b1, 1'b0, 30);
        for (i = 0; i < 5; i = i + 1) begin
            cycle(1'b1, tmp8, 1'b0);
            tmp8 = tmp8 + 8'd1;
            chk(s_fire_m === 1'b0, 31);
        end
        // 5. Ready rises: skid beat moves forward, then no bubble
        cycle(1'b1, 8'h44, 1'b1);
        chk(s_fire_m === 1'b0 && m_fire_m === 1'b1, 32);
        peek_state(1'b1, 1'b1, 33);
        cycle(1'b1, 8'h55, 1'b1);
        chk(s_fire_m === 1'b1 && m_fire_m === 1'b1, 34);
        cycle(1'b1, 8'h66, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        peek_state(1'b0, 1'b1, 35);

        // 6. Streams with single-cycle and multi-cycle stalls
        for (i = 0; i < 32; i = i + 1) begin
            cycle(1'b1, dcount, (i % 4) != 2);
            dcount = dcount + 8'd1;
        end
        for (i = 0; i < 48; i = i + 1) begin
            cycle(1'b1, dcount, (i % 8) < 3);
            dcount = dcount + 8'd1;
        end
        for (i = 0; i < 4; i = i + 1) cycle(1'b0, 8'h00, 1'b1);
        peek_state(1'b0, 1'b1, 36);

        // 7. Random traffic against the model, with a reset mid-run
        for (i = 0; i < 3000; i = i + 1) begin
            if ((i % 250) == 0) begin
                rnd   = $random;
                thr_s = rnd[3:0] | 4'd1;
                thr_m = rnd[7:4] | 4'd1;
            end
            if (i == 1500) do_reset;
            rnd = $random;
            cycle(rnd[3:0] < thr_s, rnd[15:8], rnd[7:4] < thr_m);
        end
        // Drain
        for (i = 0; i < 4; i = i + 1) cycle(1'b0, 8'h00, 1'b1);
        chk(count == 0, 37);
        peek_state(1'b0, 1'b1, 38);

        // 8. Reset with two beats held
        cycle(1'b1, 8'h77, 1'b0);
        cycle(1'b1, 8'h88, 1'b0);
        peek_state(1'b1, 1'b0, 39);
        do_reset;
        peek_state(1'b0, 1'b1, 40);
        cycle(1'b1, 8'h99, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        cycle(1'b0, 8'h00, 1'b1);
        peek_state(1'b0, 1'b1, 41);

        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
        $finish;
    end

endmodule

`default_nettype wire
=== END FILE ===
